\question{7}{8} The following shows a sequence of figures formed by dots. The $n$th figure has $[(n+1)^2-1]$ dots.

\par\vspace{0.5em}
\noindent\hspace*{2em}%
\begin{tikzpicture}[scale=0.42,baseline=-0.8ex,every node/.style={font=\small,dot/.style={circle,fill,inner sep=1.2pt}}]
  \foreach \f/\x/\n in {1/0/1, 2/2.8/2, 3/6.8/3, 4/11.8/4} {
    \foreach \i in {0,...,\n} {
      \foreach \j in {0,...,\n} {
        \ifnum\i=\n\relax
          \ifnum\j=\n\relax\else\node[dot] at (\x+\i*0.55,\j*0.55) {};\fi
        \else
          \ifnum\j=\n\relax\else\node[dot] at (\x+\i*0.55,\j*0.55) {};\fi
        \fi
      }
    }
    \ifnum\f=1 \def\flabel{1st}\fi
    \ifnum\f=2 \def\flabel{2nd}\fi
    \ifnum\f=3 \def\flabel{3rd}\fi
    \ifnum\f=4 \def\flabel{4th}\fi
    \node[below] at (\x+\n*0.55/2,-0.45) {\flabel};
  }
\end{tikzpicture}

\begin{subparts}
  \item Find the number of dots in the 15th figure.
  \item Can a figure in the sequence have $224$ dots? Explain your answer.
  \item Is the number of dots in the 11th figure odd? Explain your answer.
\end{subparts}

\answerlines{16}

\question{8}{8} Ada is distributing stamps to $6$ friends. There are $144$ stamps with a city background, $108$ stamps with a beach background and $72$ stamps with a forest background.

\begin{subparts}
  \item Ada claims that she can distribute the stamps to all her friends evenly. Do you agree? Explain your answer.
  \item Ada now decides to pack the stamps into small bags. Only stamps with the same kind of background can be packed into the same bag. Each bag contains the same number of stamps.
  \begin{subpartsii}
    \item At most how many stamps are there in each bag?
    \item Suppose the number of stamps in each bag is the same as the number found in (b)(i). How many bags does Ada need to pack all the stamps?
  \end{subpartsii}
\end{subparts}

\answerlines{16}

